# DK FBS.  Frederiksberg - Frederiksberg Syd
#
let fs = path("d3.dk.fbs");

with detail = 4, railway = :first :nopax :removed {
    with link = "line.dk.FBS" {
        with layer = -2 track(:station,
                fs[:fre.yn + 0.9dl, :fre.yn + 1dl] << 0.5mo
            --  fs[:fre.yn + 2dl, :fre.ys] << 1.5mo
        );
        track(:station :casing,
                fs[:fre.ys - 0.1dl, :fre.ys] << 1.5mo
            ..  fs[:frs, :frs + 0.1dl] << 0.5mo
        );
    }
}

